fn api_with_notices() -> (ThemeJsonApi, Rc<RecordedDiagnostics>) {
    let blocks = MemoryBlockMetadata::new();
    blocks.register(RegisteredBlock { name: "core/group".into(), selectors: Value::Null, supports: Value::Null, style_names: vec![] });
    let notices = Rc::new(RecordedDiagnostics::default());
    let api = ThemeJsonApi::new(ThemeJsonDeps {
        blocks: Rc::new(blocks),
        text: Rc::new(LowerText),
        gettext: Rc::new(NoTranslation),
        diagnostics: notices.clone(),
    });
    (api, notices)
}

fn api() -> ThemeJsonApi {
    api_with_notices().0
}

fn pair(data: Value, notices: Vec<String>) -> Value {
    let notices = Value::Array(notices.into_iter().enumerate().map(|(i, n)| (Key::Int(i as i64), Value::Str(n))).collect());
    Value::Array(vec![(Key::Int(0), data), (Key::Int(1), notices)])
}

